using System.Security.Cryptography;
using Iskender.Core.Contracts.Identifiers;
using Iskender.Core.Contracts.Versioning;

namespace Iskender.Core.Contracts.Context;

/// <summary>
/// The gateway's own request ID: <c>req_</c> and 26 base32 characters from the same secure source as resource IDs. It is
/// always generated by the gateway and is authoritative. It is not a <see cref="ResourceId"/> and cannot be converted to one.
/// </summary>
[ContractVersion("core-contracts", 1)]
public sealed class RequestCorrelationId : IEquatable<RequestCorrelationId>
{
    internal const string Prefix = "req_";

    private RequestCorrelationId(string value)
    {
        Value = value;
    }

    /// <summary>The text, <c>req_</c> and 26 lowercase base32 characters.</summary>
    public string Value { get; }

    /// <summary>Generates a new request ID. Fails with <c>core.random_source_failed</c> if the secure source fails, with no fallback.</summary>
    public static RequestCorrelationId New() => New(RandomNumberGenerator.Fill);

    /// <summary>Test seam: generates from a supplied random source.</summary>
    internal static RequestCorrelationId New(ResourceId.RandomFill fill) => new(Prefix + ResourceId.NewBody(fill));

    public static bool operator ==(RequestCorrelationId? left, RequestCorrelationId? right) => left is null ? right is null : left.Equals(right);

    public static bool operator !=(RequestCorrelationId? left, RequestCorrelationId? right) => !(left == right);

    public bool Equals(RequestCorrelationId? other) => other is not null && string.Equals(Value, other.Value, StringComparison.Ordinal);

    public override bool Equals(object? obj) => Equals(obj as RequestCorrelationId);

    public override int GetHashCode() => StringComparer.Ordinal.GetHashCode(Value);

    public override string ToString() => Value;
}
